# Autotune XBLOCK and num_warps; grid stays static at 64 blocks
@triton.autotune(configs=[
    triton.Config({'XBLOCK': 128, 'YBLOCK': 8}, num_warps=4, num_stages=2),
    triton.Config({'XBLOCK': 256, 'YBLOCK': 8}, num_warps=4, num_stages=2),
    triton.Config({'XBLOCK': 512, 'YBLOCK': 8}, num_warps=8, num_stages=2),
    triton.Config({'XBLOCK': 1024, 'YBLOCK': 8}, num_warps=8, num_stages=2),
], key=['xnumel'])
@triton.jit
def kernel(..., YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    ...
grid = (triton.cdiv(xnumel, 8),)  # unchanged — still 64 blocks
kernel[grid](arg0, arg1, arg2, ynumel, xnumel)  # XBLOCK/YBLOCK injected by autotune

# Autotune-aware 2D lambda grid
@triton.autotune(configs=[
    triton.Config({'XBLOCK': 128, 'YBLOCK': 8}, num_warps=4, num_stages=2),
    triton.Config({'XBLOCK': 256, 'YBLOCK': 8}, num_warps=4, num_stages=2),
    triton.Config({'XBLOCK': 512, 'YBLOCK': 8}, num_warps=8, num_stages=2),
    triton.Config({'XBLOCK': 1024, 'YBLOCK': 8}, num_warps=8, num_stages=2),
], key=['xnumel'])
@triton.jit
def kernel(...):
    ...

grid = lambda meta: (
    triton.cdiv(xnumel, meta['XBLOCK']),
    triton.cdiv(ynumel, meta['YBLOCK']),
)
kernel[grid](arg0, arg1, arg2, ynumel, xnumel)  # no explicit XBLOCK/YBLOCK
